CREATE FUNCTION public.release_seller_file_ownership(p_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Privileged account management only' USING ERRCODE='42501'; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user_id AND role='seller') OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user_id AND NOT is_active) THEN RAISE EXCEPTION 'Deactivate a seller before deleting the account'; END IF; UPDATE storage.objects SET owner=NULL,owner_id=NULL WHERE owner_id=p_user_id::text OR owner=p_user_id; END $$;
REVOKE ALL ON FUNCTION public.release_seller_file_ownership(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.release_seller_file_ownership(uuid) TO service_role;